import crypto from 'node:crypto';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

/**
 * Build the Phase 6 mandatory RISC-V64 corpus from the frozen profile.
 *
 * The corpus is generated by invoking the exact pinned toolchain, not by
 * trusting that "Clang supports RISC-V". If the frozen compiler/linker identity
 * is not available the build fails closed; a missing toolchain is BLOCKING, not
 * a skip.
 */

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../..');
const PROFILE = JSON.parse(fs.readFileSync(path.join(ROOT, 'tools/validation/phase6/profile.json'), 'utf8'));
const SOURCE = path.join(ROOT, PROFILE.corpus.source);

function sha256(bytes) { return crypto.createHash('sha256').update(bytes).digest('hex'); }

function run(executable, args, options = {}) {
  const result = spawnSync(executable, args, {
    encoding: 'utf8',
    cwd: options.cwd ?? ROOT,
    env: { ...process.env, LC_ALL: 'C', LANG: 'C', SOURCE_DATE_EPOCH: '0' },
    maxBuffer: 64 * 1024 * 1024,
  });
  if (result.error) throw result.error;
  if (result.status !== 0) {
    throw new Error(`command failed (${result.status}): ${executable} ${args.join(' ')}\n${result.stdout ?? ''}\n${result.stderr ?? ''}`);
  }
  return result;
}

function firstExecutable(candidates) {
  for (const candidate of candidates) {
    if (candidate.includes('/') ? fs.existsSync(candidate) : spawnSync('bash', ['-lc', `command -v ${candidate}`], { encoding: 'utf8' }).status === 0) return candidate;
  }
  return null;
}

export function probeToolchain() {
  const clang = firstExecutable(['/usr/bin/clang-18', 'clang-18', '/usr/bin/clang', 'clang']);
  const lld = firstExecutable(['/usr/bin/ld.lld-18', 'ld.lld-18', '/usr/bin/ld.lld', 'ld.lld']);
  const objdump = firstExecutable(['/usr/bin/llvm-objdump-18', 'llvm-objdump-18', '/usr/bin/llvm-objdump', 'llvm-objdump']);
  const readobj = firstExecutable(['/usr/bin/llvm-readobj-18', 'llvm-readobj-18', '/usr/bin/llvm-readobj', 'llvm-readobj']);
  const compilerVersion = clang ? run(clang, ['--version']).stdout.trim() : null;
  const linkerVersion = lld ? run(lld, ['--version']).stdout.trim() : null;
  // Upstream support for a target is not evidence that this build has it.
  const targets = clang ? run(clang, ['-print-targets']).stdout : '';
  const exactCompiler = Boolean(compilerVersion?.includes(PROFILE.toolchain.compilerVersionContains));
  const exactLinker = Boolean(linkerVersion?.includes(PROFILE.toolchain.linkerVersionContains));
  const riscv64Target = /(^|\s)riscv64\s/m.test(targets);
  return Object.freeze({
    clang, lld, objdump, readobj, compilerVersion, linkerVersion,
    host: process.arch,
    exactCompiler, exactLinker, riscv64Target,
    exact: exactCompiler && exactLinker && riscv64Target && Boolean(objdump) && Boolean(readobj),
  });
}

function optimizationFlag(level) {
  if (!PROFILE.corpus.mandatoryOptimizationLevels.includes(level)) throw new TypeError(`unsupported optimization: ${level}`);
  return `-${level}`;
}

function targetFlagsFor(target) {
  if (target.id === 'riscv64-lp64-exec') return ['-fno-pic', '-Wl,-Ttext=0x10000'];
  if (target.id === 'riscv64-lp64-pie') return ['-fPIE', '-Wl,-pie'];
  throw new TypeError(`unknown Phase 6 corpus target: ${target.id}`);
}

function buildOne({ toolchain, target, optimization, outDir }) {
  const output = path.join(outDir, `p6-${target.id}-${optimization}.elf`);
  const flags = [
    `--target=${PROFILE.toolchain.targetTriple}`,
    `-march=${PROFILE.isaProfile.id}`,
    `-mabi=${target.abiId}`,
    '-std=c11',
    optimizationFlag(optimization),
    '-fno-stack-protector',
    '-nostdlib',
    '-fuse-ld=lld',
    '-Wl,--build-id=none',
    '-Wl,-e,p6_entry',
    ...targetFlagsFor(target),
    SOURCE,
    '-o', output,
  ];
  run(toolchain.clang, flags);
  const bytes = fs.readFileSync(output);
  const objectMetadata = run(toolchain.readobj, ['--file-headers', '--sections', '--symbols', '--relocations', '--dynamic-table', output]).stdout;
  const disassembly = run(toolchain.objdump, ['-d', '--print-imm-hex', '--show-all-symbols', output]).stdout;
  return Object.freeze({
    id: `${target.id}-${optimization}`,
    target: target.id,
    elfType: target.elfType,
    abiId: target.abiId,
    optimization,
    path: output,
    flags,
    sha256: sha256(bytes),
    size: bytes.length,
    bytes,
    disassembly,
    objectMetadata,
  });
}

export function buildPhase6VerificationCorpus({ outDir = fs.mkdtempSync(path.join(os.tmpdir(), 'hex-p6-corpus-')) } = {}) {
  const toolchain = probeToolchain();
  if (!toolchain.exact) {
    const error = new Error(`Phase 6 exact frozen toolchain unavailable: ${JSON.stringify(toolchain)}`);
    error.code = 'P6_TOOLCHAIN_MISMATCH';
    throw error;
  }
  fs.mkdirSync(outDir, { recursive: true });
  const sourceBytes = fs.readFileSync(SOURCE);
  const fixtures = [];
  for (const target of PROFILE.corpus.mandatoryTargets) {
    for (const optimization of PROFILE.corpus.mandatoryOptimizationLevels) {
      fixtures.push(buildOne({ toolchain, target, optimization, outDir }));
    }
  }
  return Object.freeze({
    schemaVersion: 'phase6-generated-corpus/v1',
    corpusId: PROFILE.corpus.id,
    profileVersion: PROFILE.profileVersion,
    toolchain,
    source: { path: path.relative(ROOT, SOURCE).replaceAll('\\', '/'), sha256: sha256(sourceBytes) },
    fixtures,
  });
}

/** Digest that binds evidence to this exact corpus content. */
export function corpusDigest(result) {
  const hash = crypto.createHash('sha256');
  hash.update(result.corpusId);
  hash.update('\0');
  hash.update(result.source.sha256);
  for (const fixture of [...result.fixtures].sort((left, right) => left.id.localeCompare(right.id))) {
    hash.update('\0');
    hash.update(fixture.id);
    hash.update('\0');
    hash.update(fixture.sha256);
  }
  return hash.digest('hex');
}

function emit(result) {
  console.log(`P6_CORPUS_PROVENANCE=${JSON.stringify({
    schemaVersion: result.schemaVersion,
    corpusId: result.corpusId,
    corpusDigest: corpusDigest(result),
    profileVersion: result.profileVersion,
    toolchain: result.toolchain,
    source: result.source,
    fixtures: result.fixtures.map(({ bytes, disassembly, objectMetadata, path: fixturePath, ...fixture }) => ({
      ...fixture,
      path: path.basename(fixturePath),
      disassemblySha256: sha256(Buffer.from(disassembly)),
      objectMetadataSha256: sha256(Buffer.from(objectMetadata)),
    })),
  })}`);
}

const isMain = process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isMain) {
  if (process.argv.includes('--probe-only')) {
    const result = probeToolchain();
    console.log(`P6_TOOLCHAIN=${JSON.stringify(result)}`);
    if (!result.exact) process.exitCode = 2;
  } else {
    try { emit(buildPhase6VerificationCorpus()); }
    catch (error) {
      console.error(error?.stack ?? String(error));
      process.exitCode = error?.code === 'P6_TOOLCHAIN_MISMATCH' ? 2 : 1;
    }
  }
}
